{"findings":[{"tipo":"GC","causa_raiz":"Alocação excessiva de memória gerenciada (2,63 MB em um único frame), disparando uma coleta de lixo síncrona (GC Collect) que paralisou a CPU por 17,94 ms. Esse comportamento decorre tipicamente de instanciação frequente de objetos, concatenação de strings contínua, criação repetitiva de coleções/arrays dentro de loops de Update ou uso de LINQ.","codigo_refatorado":"using UnityEngine;
using System.Collections.Generic;

public class OptimizedEntitySpawner : MonoBehaviour
{
    [SerializeField] private GameObject prefab;
    [SerializeField] private int poolSize = 50;

    private readonly Queue<GameObject> pool = new Queue<GameObject>();
    private readonly Collider[] hitBuffer = new Collider[10];

    private void Awake()
    {
        for (int i = 0; i < poolSize; i++)
        {
            GameObject obj = Instantiate(prefab, transform);
            obj.SetActive(false);
            pool.Enqueue(obj);
        }
    }

    public GameObject GetPooledObject(Vector3 position, Quaternion rotation)
    {
        GameObject obj = pool.Count > 0 ? pool.Dequeue() : Instantiate(prefab);
        obj.transform.SetPositionAndRotation(position, rotation);
        obj.SetActive(true);
        return obj;
    }

    public void ReturnToPool(GameObject obj)
    {
        obj.SetActive(false);
        pool.Enqueue(obj);
    }

    public int CheckNonAllocPhysics(Vector3 center, float radius, int layerMask)
    {
        return Physics.OverlapSphereNonAlloc(center, radius, hitBuffer, layerMask);
    }
}","explicacao_didatica":"O Coletor de Lixo (Garbage Collector) pausa o jogo para limpar objetos descartados na memória RAM. Alocar mais de 2.6 MB de uma só vez força o motor a parar tudo por quase 18 milissegundos para fazer essa faxina. Para resolver isso, reutilizamos os objetos através de Object Pooling em vez de criá-los e destruí-los o tempo todo, além de usar métodos 'NonAlloc' para cálculos físicos sem gerar lixo de memória."}],"dicas_level_design":null}

